struct Bear { virtual ~Bear() = default; };
struct Panda : public Bear {};
struct Grizzly : public Bear {};

// Overloading resolves by declared reference type, not runtime type
void process(const Panda& p) { /* Specific logic */ }
void process(const Bear& b) { /* Generic fallback */ }

Panda p_obj;
Grizzly g_obj;

// Binding Resolution Examples:
process(p_obj);     // Binds to Panda& (Exact match)
process(g_obj);     // Binds to Bear& (Conversion match)

Bear& ref_p = p_obj;
process(ref_p);     // Binds to Bear& (Based on declared type)
                    // Note: This differs from virtual dispatch.
